UPDATE TBL_QUOTE
   SET STATUS = '03'
 WHERE QUOTE_ID = #{quoteId}
   AND STATUS = '02'
   AND EXPIRES_AT > SYSDATE
   AND UPDATED_AT = #{updatedAt}
